import React, { useEffect, useState } from 'react';
import { getExamData, deleteUserExamData, updateExamData } from '../services/api';

const ExamData = () => {
  const [examData, setExamData] = useState({
    examName: '',
    date: '',
    durationInMinutes: '',
    status: 'inprogress',
    franchiseId: '',
    name: '',
  });
  const [examDataList, setExamDataList] = useState([]);
  const [filteredExamData, setFilteredExamData] = useState([]);
  const [franchiseList, setFranchiseList] = useState([]);
  const [durationList, setDurationList] = useState([]);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [selectedFranchise, setSelectedFranchise] = useState('');
  const [editingExamId, setEditingExamId] = useState(null);

  const validExamNames = [
    'ServiceNow: CAD', 'ServiceNow: CSA', 'ServiceNow: Platform Developer',
    'ServiceNow: HR AND IMPLEMENTATION', 'ServiceNow: CLOUD ARCHITECTURE',
    'Salesforce developer', 'Salesforce administrators', 'Google cloud',
    'Mulesoft', 'Fusion', 'PSI'
  ];
  const validStatuses = ['completed', 'absent', 'inprogress'];

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [franchiseData, durationData] = await Promise.all([
          getExamData(), // Get Exam Data & Associated Franchises
          fetchDurationOptions(), // Assuming this function fetches duration options
        ]);

        if (!Array.isArray(franchiseData) || franchiseData.length === 0) {
          throw new Error('No associated franchises found for the user.');
        }
        if (!Array.isArray(durationData.options) || durationData.options.length === 0) {
          throw new Error('No exam durations available.');
        }

        setFranchiseList(franchiseData[0]); // Assuming this is the structure
        setDurationList(durationData.options);
        setExamDataList(franchiseData.flatMap(franchise =>
          (franchise.examData || []).map(exam => ({
            franchiseId: franchise._id,
            franchiseName: franchise.name,
            name: exam.name,
            examName: exam.examName,
            date: exam.date,
            duration: exam.durationInMinutes,
            status: exam.status,
            examId: exam._id,
          }))
        ));
        setFilteredExamData(franchiseData.flatMap(franchise =>
          (franchise.examData || []).map(exam => ({
            franchiseId: franchise._id,
            franchiseName: franchise.name,
            name: exam.name,
            examName: exam.examName,
            date: exam.date,
            duration: exam.durationInMinutes,
            status: exam.status,
            examId: exam._id,
          }))
        ));
      } catch (error) {
        setError(error.message || 'Failed to fetch data.');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  // Filter exams by selected franchise
  const handleFranchiseChange = (e) => {
    const franchiseName = e.target.value;
    setSelectedFranchise(franchiseName);

    if (franchiseName === '') {
      setFilteredExamData(examDataList); // Show all data if no franchise is selected
    } else {
      setFilteredExamData(examDataList.filter(exam => exam.franchiseName === franchiseName));
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setExamData((prevData) => ({
      ...prevData,
      [name]: name === 'durationInMinutes' ? parseInt(value, 10) : value,
    }));
  };

  const validateForm = () => {
    if (!examData.name.trim()) return 'Please provide the full name.';
    if (!examData.examName || !validExamNames.includes(examData.examName)) return 'Please select a valid exam name.';
    if (!examData.status || !validStatuses.includes(examData.status.toLowerCase())) return 'Please select a valid status.';
    if (!examData.date) return 'Please provide the exam date.';
    const examDate = new Date(examData.date);
    if (isNaN(examDate.getTime())) return 'Invalid date format.';
    if (isNaN(examData.durationInMinutes) || examData.durationInMinutes <= 0) return 'Please select a valid exam duration.';
    if (!examData.franchiseId) return 'Please select a franchise.';
    return null;
  };

  const handleCreateExamData = async (e) => {
    e.preventDefault();
    const validationError = validateForm();
    if (validationError) {
      setError(validationError);
      return;
    }

    setLoading(true);
    try {
      const payload = {
        examData: [{
          name: examData.name,
          examName: examData.examName,
          date: new Date(examData.date).toISOString().split('T')[0],
          durationInMinutes: examData.durationInMinutes,
          status: examData.status.toLowerCase(),
          franchiseId: examData.franchiseId,
        }],
      };

      await createUserExamData(payload.examData, examData.franchiseId); // Assuming this function handles the API call
      setSuccess('Exam data created successfully!');
      setExamData({
        examName: '',
        date: '',
        durationInMinutes: '',
        status: 'inprogress',
        franchiseId: '',
        name: '',
      });
      setError(null);
    } catch (error) {
      setError(error.response?.data?.message || error.message || 'Failed to create exam data.');
    } finally {
      setLoading(false);
    }
  };

  const handleEditClick = (exam) => {
    setEditingExamId(exam.examId);
    setExamData({
      name: exam.name,
      examName: exam.examName,
      date: exam.date,
      durationInMinutes: exam.duration,
      status: exam.status,
      franchiseId: exam.franchiseId,
    });
  };

  const handleSave = async () => {
    const validationError = validateForm();
    if (validationError) {
      setError(validationError);
      return;
    }

    setLoading(true);
    try {
      const payload = {
        examData: [{
          name: examData.name,
          examName: examData.examName,
          date: new Date(examData.date).toISOString().split('T')[0],
          durationInMinutes: examData.durationInMinutes,
          status: examData.status.toLowerCase(),
          franchiseId: examData.franchiseId,
        }],
      };

      await updateExamData(examData.franchiseId, editingExamId, payload); // Assuming this function handles the update API call
      setSuccess('Exam data updated successfully!');
      setExamData({
        examName: '',
        date: '',
        durationInMinutes: '',
        status: 'inprogress',
        franchiseId: '',
        name: '',
      });
      setEditingExamId(null);
      setError(null);
    } catch (error) {
      setError(error.response?.data?.message || error.message || 'Failed to update exam data.');
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (examId, franchiseId) => {
    try {
      await deleteUserExamData(franchiseId, examId);
      setExamDataList((prevState) => prevState.filter(exam => exam.examId !== examId));
      setFilteredExamData((prevState) => prevState.filter(exam => exam.examId !== examId));
    } catch (error) {
      setError(error.response?.data?.message || error.message || 'Failed to delete exam data.');
    }
  };

  useEffect(() => {
    if (success) {
      const timer = setTimeout(() => setSuccess(''), 3000);
      return () => clearTimeout(timer);
    }
  }, [success]);

  return (
    <div style={styles.container}>
      <h2 style={styles.header}>Exam Data</h2>

      {loading && <p style={styles.loading}>Loading...</p>}
      {error && <p style={styles.error}>{error}</p>}
      {success && <p style={styles.success}>{success}</p>}

      <h3 style={styles.formTitle}>Create Exam Data</h3>
      <form onSubmit={handleCreateExamData} style={styles.form}>
        <div style={styles.formGroup}>
          <label htmlFor="franchiseId" style={styles.label}>Select Franchise</label>
          <select
            name="franchiseId"
            value={examData.franchiseId}
            onChange={handleChange}
            required
            style={styles.input}
          >
            <option value="">Select a franchise</option>
            {franchiseList.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name}
              </option>
            ))}
          </select>
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="userFullName" style={styles.label}>Full Name</label>
          <input
            type="text"
            name="name"
            value={examData.name}
            onChange={handleChange}
            required
            style={styles.input}
          />
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="examName" style={styles.label}>Exam Name</label>
          <select
            name="examName"
            value={examData.examName}
            onChange={handleChange}
            required
            style={styles.input}
          >
            <option value="">Select an exam</option>
            {validExamNames.map((exam, index) => (
              <option key={index} value={exam}>{exam}</option>
            ))}
          </select>
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="date" style={styles.label}>Exam Date</label>
          <input
            type="date"
            name="date"
            value={examData.date}
            onChange={handleChange}
            required
            style={styles.input}
          />
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="durationInMinutes" style={styles.label}>Duration (Minutes)</label>
          <select
            name="durationInMinutes"
            value={examData.durationInMinutes}
            onChange={handleChange}
            required
            style={styles.input}
          >
            <option value="">Select duration</option>
            {durationList.map((duration) => (
              <option key={duration} value={duration}>{duration} minutes</option>
            ))}
          </select>
        </div>

        <div style={styles.formGroup}>
          <label htmlFor="status" style={styles.label}>Status</label>
          <select
            name="status"
            value={examData.status}
            onChange={handleChange}
            required
            style={styles.input}
          >
            <option value="inprogress">In Progress</option>
            <option value="completed">Completed</option>
            <option value="absent">Absent</option>
          </select>
        </div>

        <button type="submit" disabled={loading} style={styles.submitButton}>
          {loading ? 'Submitting...' : 'Create Exam Data'}
        </button>
      </form>

      {/* List of existing exams */}
      <div style={styles.listContainer}>
        <h3 style={styles.formTitle}>Exam Data List</h3>
        <div style={styles.list}>
          {filteredExamData.map((exam) => (
            <div key={exam.examId} style={styles.examItem}>
              <span>{exam.name} - {exam.examName} ({exam.status})</span>
              <button onClick={() => handleEditClick(exam)} style={styles.editButton}>Edit</button>
              <button onClick={() => handleDelete(exam.examId, exam.franchiseId)} style={styles.deleteButton}>Delete</button>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

const styles = {
  container: {
    padding: '20px',
    border: '1px solid #ddd',
    borderRadius: '5px',
  },
  header: {
    textAlign: 'center',
  },
  formGroup: {
    marginBottom: '15px',
  },
  label: {
    display: 'block',
    fontWeight: 'bold',
  },
  input: {
    width: '100%',
    padding: '8px',
    marginTop: '5px',
  },
  submitButton: {
    padding: '10px 20px',
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    cursor: 'pointer',
    marginTop: '15px',
  },
  formTitle: {
    marginBottom: '15px',
  },
  error: {
    color: 'red',
  },
  success: {
    color: 'green',
  },
  loading: {
    fontStyle: 'italic',
  },
  listContainer: {
    marginTop: '30px',
  },
  list: {
    marginTop: '10px',
  },
  examItem: {
    marginBottom: '10px',
    display: 'flex',
    justifyContent: 'space-between',
  },
  editButton: {
    backgroundColor: '#ffc107',
    color: '#fff',
    padding: '5px 10px',
    border: 'none',
    cursor: 'pointer',
  },
  deleteButton: {
    backgroundColor: '#dc3545',
    color: '#fff',
    padding: '5px 10px',
    border: 'none',
    cursor: 'pointer',
  },
};

export default ExamData;
